    "uc_descripciones": {
      "QUIC0101_3": "Gestionar la planificación, organización y coordinación de operaciones de producción de productos farmacéuticos, biotecnológicos y afines.",
      "QUIC0102_3": "Garantizar el cumplimiento normativo en la industria farmacéutica, biotecnológica y afín.",
      "QUIC0201_3": "Supervisar y coordinar los servicios auxiliares en la industria farmacéutica, biotecnológica y afín.",
      "QUIC0202_3": "Controlar el mantenimiento de equipos e instalaciones en la industria farmacéutica, biotecnológica y afín.",
      "QUIC0301_3": "Realizar operaciones de análisis y control de calidad de productos farmacéuticos, biotecnológicos y afines.",
      "QUIC0302_3": "Aplicar técnicas instrumentales en análisis de calidad.",
      "QUIC0303_3": "Garantizar la calidad del proceso productivo.",
      "QUIC0401_3": "Gestionar sistemas de seguridad y protección ambiental en la industria farmacéutica, biotecnológica y afín.",
      "QUIC0402_3": "Aplicar medidas de prevención de riesgos laborales y protección ambiental.",
      "QUIC0501_3": "Realizar operaciones básicas de laboratorio y producción en la industria farmacéutica, biotecnológica y afín.",
      "QUIC0502_3": "Aplicar técnicas de manipulación de productos farmacéuticos, biotecnológicos y afines.",
      "QUIC0601_3": "Ejecutar procesos de producción farmacéutica mediante técnicas convencionales.",
      "QUIC0602_3": "Optimizar parámetros de proceso en la producción de medicamentos.",
      "QUIC0701_3": "Ejecutar procesos de producción biotecnológica.",
      "QUIC0702_3": "Aplicar técnicas de fermentación y cultivo celular.",
      "QUIC0801_3": "Ejecutar operaciones de acondicionamiento de productos farmacéuticos, biotecnológicos y afines.",
      "QUIC0802_3": "Gestionar sistemas de almacenamiento y distribución de productos farmacéuticos, biotecnológicos y afines.",
      "QUIC0901_3": "Cumplir y hacer cumplir la normativa reguladora de la industria farmacéutica, biotecnológica y afín.",
      "QUIC1001_3": "Aplicar conceptos y procesos de biotecnología en la producción de productos farmacéuticos y afines.",
      "QUIC1002_3": "Ejecutar técnicas analíticas en biotecnología."
    },
